import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

reverse_cumsum_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void reverse_cumsum_kernel(const float* x, float* y, int B, int T) 
{
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    if (b < B) {
        float partial_sum = 0.0f;
        for (int i = T - 1; i >= 0; i--) {
            partial_sum += x[b * T + i];
            y[b * T + i] = partial_sum;
        }
    }
}

torch::Tensor reverse_cumsum_cuda(torch::Tensor x) {
    TORCH_CHECK(x.dim() == 2, "Expected a 2D tensor ([B, T]) for reverse cumsum along dim=1.");

    int B = x.size(0);
    int T = x.size(1);
    auto y = torch::empty_like(x);

    const int block_size = 128;
    const int grid_size = (B + block_size - 1) / block_size;

    reverse_cumsum_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        B,
        T
    );

    return y;
}
""";

reverse_cumsum_cpp_source = r"torch::Tensor reverse_cumsum_cuda(torch::Tensor x);"

reverse_cumsum = load_inline(
    name="reverse_cumsum",
    cpp_sources=reverse_cumsum_cpp_source,
    cuda_sources=reverse_cumsum_source,
    functions=["reverse_cumsum_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    A model that performs a reverse cumulative sum operation along dim=1 using a custom CUDA kernel.
    """
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x):
        # This implementation assumes a 2D shape [B, T] when dim=1
        return reverse_cumsum.reverse_cumsum_cuda(x)
